 await using(var db=await factory.CreateDbContextAsync()){db.EventReceptions.Add(new(){Id=Guid.NewGuid().ToString(),EventId="event",UserId="racer",ActorId="admin",At="2026-10-01T00:00:00.000Z"});await Deny<DbUpdateException>(()=>db.SaveChangesAsync(),"Database unique index independently rejects duplicate active receipt");}
 await Deny<UnauthorizedAccessException>(()=>core.ReadReceptionHistoryAsync(new ClaimsPrincipal(),"event"),"Anonymous cannot read event receipt history");await Deny<UnauthorizedAccessException>(()=>core.ReadReceptionHistoryAsync(viewer,"event"),"Forged role/member cannot read receipt history");await Deny<UnauthorizedAccessException>(()=>core.ReadReceptionHistoryAsync(manager,"other"),"Manager cannot read another event receipt history");await Deny<UnauthorizedAccessException>(()=>core.ReadReceptionHistoryAsync(admin,"missing"),"Unknown event history denied");
