 var firstPage=await core.ReadReceptionHistoryAsync(manager,"event","performer");Check(firstPage.Receipts.Length==100&&firstPage.Next is not null,"Receipt history first page is bounded with continuation");var secondPage=await core.ReadReceptionHistoryAsync(manager,"event","performer",firstPage.Next);Check(secondPage.Receipts.Length==6&&secondPage.Next is null&&secondPage.Receipts.All(x=>firstPage.Receipts.All(y=>y.Receipt.Id!=x.Receipt.Id)),"Equal timestamp GUID cursor traverses all older receipts without duplicates or gaps");Check(firstPage.Receipts.Concat(secondPage.Receipts).Select(x=>x.Receipt.Id).Distinct().Count()==106,"All filtered receipt rows covered exactly once");Check(firstPage.Receipts.All(x=>x.CurrentlyRegistered)&&secondPage.Receipts.All(x=>x.CurrentlyRegistered),"History membership marker reflects current registration");Check((await core.ReadReceptionRosterAsync(admin,"event")).CompletedCount==completedBefore,"Historical cancelled receipt pages never alter current completion denominator");
